        in_reply_to: l.in_reply_to_status_id_str || undefined,
        created_at: l.created_at,
        url: `https://x.com/${screenName}/status/${tw.rest_id}`,
        ...extractMedia(l),
        card: extractCard(tw),
        quoted_tweet: extractQuotedTweet(tw),
