xiaohongshu.note:
/**
 * Xiaohongshu note — read full note content from a public note page.
 *
 * Extracts title, author, description text, and engagement metrics
 * (likes, collects, comment count) via DOM extraction.
 *
 * Requires a full Xiaohongshu note URL with xsec_token.
 */
import { cli, Strategy } from '@jackwener/opencli/registry';
import { AuthRequiredError, EmptyResultError } from '@jackwener/opencli/errors';
import { parseNoteId, buildNoteUrl } from './note-helpers.js';
import { readXhsDetailPage } from './risk-control.js';
/**
 * Host-agnostic IIFE that scrapes note title / author / counts / tags from a
 * rendered note detail page. Exported so the rednote adapter can reuse the
 * exact same selector set without copying it.
 */
export const NOTE_EXTRACT_JS = `
      (() => {
        const bodyText = document.body?.innerText || ''
        const loginWall = /登录后查看|请登录/.test(bodyText)
        const notFound = /页面不见了|笔记不存在|无法浏览/.test(bodyText)
        const securityBlock = /安全限制|访问链接异常/.test(bodyText)
          || /website-login\\/error|error_code=300017|error_code=300031/.test(location.href)

        const clean = (el) => (el?.textContent || '').replace(/\\s+/g, ' ').trim()

        // Scope the note's own fields to #noteContainer — the detail panel.
        // The page also renders a recommendation feed next to the note, and
        // every card in that feed carries a .title. querySelector returns the
        // FIRST match in document order, so for a note that has no title of
        // its own (#detail-title absent) the unscoped selector fell through to
        // .title and reported an unrelated recommendation card's title as this
        // note's title. Same class of bug as the .interact-container scoping
        // below.
        const scope = document.querySelector('#noteContainer')
        const title = scope
          ? clean(scope.querySelector('#detail-title, .title'))
          : clean(document.querySelector('#detail-title'))
        const desc = scope
          ? clean(scope.querySelector('#detail-desc, .desc, .note-text'))
          : clean(document.querySelector('#detail-desc, .note-text'))
        const author = scope
          ? clean(scope.querySelector('.username, .author-wrapper .name'))
          : clean(document.querySelector('.username, .author-wrapper .name'))
        // Scope to .interact-container — the post's main interaction bar.
        // Without scoping, .like-wrapper / .chat-wrapper also match each
        // comment's like/reply buttons in the comment section, and
        // querySelector returns the FIRST match (a comment's count, not the
        // post's). The post's true counts live inside .interact-container.
        const likes = clean(document.querySelector('.interact-container .like-wrapper .count'))
        const collects = clean(document.querySelector('.interact-container .collect-wrapper .count'))
        const comments = clean(document.querySelector('.interact-container .chat-wrapper .count'))

        // Try to extract tags/topics
        const tags = []
        document.querySelectorAll('#detail-desc a.tag, #detail-desc a[href*="search_result"]').forEach(el => {
          const t = (el.textContent || '').trim()
          if (t) tags.push(t)
        })

        return { pageUrl: location.href, securityBlock, loginWall, notFound, title, desc, author, likes, collects, comments, tags }
      })()
    `;
export const command = cli({
    site: 'xiaohongshu',
    name: 'note',
    access: 'read',
    description: '获取小红书笔记正文和互动数据',
    domain: 'www.xiaohongshu.com',
    strategy: Strategy.COOKIE,
    navigateBefore: false,
    args: [
        { name: 'note-id', required: true, positional: true, help: 'Full Xiaohongshu note URL with xsec_token' },
    ],
    columns: ['field', 'value'],
    func: async (page, kwargs) => {
        const raw = String(kwargs['note-id']);
        const noteId = parseNoteId(raw);
        const url = buildNoteUrl(raw, { commandName: 'xiaohongshu note' });
        // readXhsDetailPage paces the navigation and retries once through a
        // cooldown if risk control soft-blocks the page (throws SECURITY_BLOCK
        // when still blocked after the retry).
        const data = await readXhsDetailPage(page, {
            url,
            extractJs: NOTE_EXTRACT_JS,
            securityHelp: /^https?:\/\//.test(raw)
                ? 'The page may be temporarily restricted. Try again later or from a different session.'
                : 'Try using a full URL from search results (with xsec_token) instead of a bare note ID.',
        });
        if (!data || typeof data !== 'object') {
            throw new EmptyResultError('xiaohongshu/note', 'Unexpected evaluate response');
        }
        if (data.loginWall) {
            throw new AuthRequiredError('www.xiaohongshu.com', 'Note content requires login');
        }
        if (data.notFound) {
            throw new EmptyResultError('xiaohongshu/note', `Note ${noteId} not found or unavailable — it may have been deleted or restricted`);
        }
        const d = data;
        // XHS renders placeholder text like "赞"/"收藏"/"评论" when count is 0;
        // normalize to '0' unless the value looks numeric.
        const numOrZero = (v) => /^\d+/.test(v) ? v : '0';
        // A note may legitimately have no title, but a real note page always
        // renders an author. If both are missing, the page failed to load.
        if (!d.title && !d.author) {
            throw new EmptyResultError('xiaohongshu/note', 'The note page loaded without visible content. The note may be deleted or restricted.');
        }
        const rows = [
            { field: 'title', value: d.title || '' },
            { field: 'author', value: d.author || '' },
            { field: 'content', value: d.desc || '' },
            { field: 'likes', value: numOrZero(d.likes || '') },
            { field: 'collects', value: numOrZero(d.collects || '') },
            { field: 'comments', value: numOrZero(d.comments || '') },
        ];
        if (d.tags?.length) {
            rows.push({ field: 'tags', value: d.tags.join(', ') });
        }
        return rows;
    },
});

xiaohongshu.extract:
function extractSearchRows(webHost) {
    const normalizeUrl = (href) => {
        if (!href)
            return '';
        try {
            const parsed = new URL(href, `https://${webHost}/`);
            if (parsed.protocol !== 'https:' || parsed.hostname.toLowerCase() !== webHost.toLowerCase())
                return '';
            return parsed.href;
        }
        catch {
            return '';
        }
    };
    const cleanText = (value) => (value || '').replace(/\s+/g, ' ').trim();
    const isVisibleNote = (el) => {
        const rect = el.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0)
            return false;
        const style = getComputedStyle(el);
        return style.display !== 'none' && style.visibility !== 'hidden';
    };
    const results = [];
    const seen = new Set();
    // Note containers: legacy `section.note-item` first, fallback to any
    // `<section>` wrapping a search-result/explore link (#1506 reports the
    // class being dropped on some xhs renders).
    const collectNoteCards = () => {
        const classMatches = document.querySelectorAll('section.note-item');
        if (classMatches.length > 0)
            return classMatches;
        const sections = new Set();
        for (const a of document.querySelectorAll('a[href*="/search_result/"], a[href*="/explore/"]')) {
            const section = a.closest('section');
            if (section)
                sections.add(section);
        }
        return sections;
    };
    for (const el of collectNoteCards()) {
        // Skip "related searches" sections
        if (el.classList?.contains('query-note-item'))
            continue;
        if (!isVisibleNote(el))
            continue;
        const titleEl = el.querySelector('.title, .note-title, a.title, .footer .title span');
        const nameEl = el.querySelector('a.author .name, .author-name, .nick-name, .name');
        const authorWrapEl = el.querySelector('a.author');
        let author = cleanText(nameEl?.textContent || '');
        if (!author && authorWrapEl) {
            const nameChild = authorWrapEl.querySelector('.name');
            author = nameChild ? cleanText(nameChild.textContent || '') : stripXhsAuthorDateSuffix(authorWrapEl.textContent || '');
        }
        const likesEl = el.querySelector('.count, .like-count, .like-wrapper .count');
        // Prefer search_result link (preserves xsec_token) over generic /explore/ link
        const detailLinkEl = el.querySelector('a.cover.mask') ||
            el.querySelector('a[href*="/search_result/"]') ||
            el.querySelector('a[href*="/explore/"]') ||
            el.querySelector('a[href*="/note/"]');
        const authorLinkEl = el.querySelector('a.author, a[href*="/user/profile/"]');
        const url = normalizeUrl(detailLinkEl?.getAttribute('href') || '');
        if (!url)
            continue;
        const key = url;
        if (seen.has(key))
            continue;
        seen.add(key);
        // Fallback title: the new bare-section render keeps the note caption
        // inside the search_result anchor's first span, not in a class-named
        // .title element. Pull from there when the class-based pick is empty.
        let title = cleanText(titleEl?.textContent || '');
        if (!title) {
            const captionSpan = detailLinkEl?.querySelector('span');
            title = cleanText(captionSpan?.textContent || '');
        }
        results.push({
            title,
            author,
            likes: cleanText(likesEl?.textContent || '0'),
            url,
            author_url: normalizeUrl(authorLinkEl?.getAttribute('href') || ''),
        });
    }
    return results;
}

xiaohongshu.merge:
export function mergeHarvestedRow(acc, row, webHost = '') {
    const url = typeof row?.url === 'string' ? row.url : '';
    const info = noteUrlInfo(url, webHost);
    const key = info.key;
    if (!key)
        return false;
    const prev = acc.get(key);
    if (!prev) {
        acc.set(key, { ...row });
        return true;
    }
    let changed = false;
    for (const field of ['title', 'author', 'author_url']) {
        if (!prev[field] && row?.[field]) {
            prev[field] = row[field];
            changed = true;
        }
    }
    if ((!prev.likes || prev.likes === '0') && row?.likes && row.likes !== '0') {
        prev.likes = row.likes;
        changed = true;
    }
    if (info.signed && !noteUrlInfo(prev.url, webHost).signed) {
        prev.url = url;
        changed = true;
    }
    return changed;
}

xiaohongshu.mapCollectionNote:
export function mapCollectionNote(entry, options = {}) {
    if (!isObject(entry))
        return null;
    const noteCard = entry.note_card ?? entry.noteCard ?? entry;
    const noteId = toCleanString(entry.note_id
        ?? entry.noteId
        ?? entry.id
        ?? noteCard.note_id
        ?? noteCard.noteId
        ?? noteCard.id);
    if (!noteId)
        return null;
    const user = noteCard.user ?? entry.user ?? {};
    const userId = toCleanString(user.user_id ?? user.userId ?? '');
    const xsecToken = toCleanString(entry.xsec_token
        ?? entry.xsecToken
        ?? noteCard.xsec_token
        ?? noteCard.xsecToken);
    if (!xsecToken)
        return null;
    const interact = noteCard.interact_info ?? noteCard.interactInfo ?? entry.interact_info ?? entry.interactInfo ?? {};
    const url = userId
        ? buildXhsNoteUrl(userId, noteId, xsecToken)
        : `https://www.xiaohongshu.com/explore/${encodeURIComponent(noteId)}?xsec_token=${encodeURIComponent(xsecToken)}&xsec_source=pc_user`;
    return {
        id: noteId,
        title: toCleanString(noteCard.display_title ?? noteCard.displayTitle ?? noteCard.title ?? entry.title ?? entry.display_title),
        author: toCleanString(user.nickname ?? user.nick_name ?? user.name),
        likes: toCleanString(interact.liked_count ?? interact.likedCount ?? 0) || '0',
        type: toCleanString(noteCard.type ?? entry.type),
        url,
    };
}

xiaohongshu.extractXhsUserNotes:
export function extractXhsUserNotes(snapshot, fallbackUserId, webHost = 'www.xiaohongshu.com') {
    const notes = flattenXhsNoteGroups(snapshot.noteGroups);
    const rows = [];
    const seen = new Set();
    for (const entry of notes) {
        const noteCard = entry?.noteCard ?? entry?.note_card ?? entry;
        if (!noteCard || typeof noteCard !== 'object')
            continue;
        const noteId = toCleanString(noteCard.noteId ?? noteCard.note_id ?? entry?.noteId ?? entry?.note_id ?? entry?.id);
        if (!noteId || seen.has(noteId))
            continue;
        seen.add(noteId);
        const userId = toCleanString(noteCard.user?.userId ?? noteCard.user?.user_id ?? fallbackUserId);
        const xsecToken = toCleanString(entry?.xsecToken ?? entry?.xsec_token ?? noteCard.xsecToken ?? noteCard.xsec_token);
        const likes = toCleanString(noteCard.interactInfo?.likedCount ?? noteCard.interact_info?.liked_count ?? 0) || '0';
        const cover = toCleanString(noteCard.cover?.urlDefault ?? noteCard.cover?.urlPre ?? noteCard.cover?.url ?? '');
        rows.push({
            id: noteId,
            title: toCleanString(noteCard.displayTitle ?? noteCard.display_title ?? noteCard.title),
            type: toCleanString(noteCard.type),
            likes,
            cover,
            url: buildXhsNoteUrl(userId || fallbackUserId, noteId, xsecToken, webHost),
        });
    }
    return rows;
}

xiaohongshu.parseXhsLikeCountText:
export function parseXhsLikeCountText(value) {
    const integerRe = /^(?:\d+|\d{1,3}(?:[,，]\d{3})+)\+?$/u;
    const shortformRe = /^((?:\d+|\d{1,3}(?:[,，]\d{3})+)(?:\.\d+)?)([wWkK万千])\+?$/u;
    const raw = String(value ?? '').replace(/\s+/g, '');
    if (!raw)
        return 0;
    if (integerRe.test(raw))
        return Number(raw.replace(/[,+，]/g, ''));
    const short = raw.match(shortformRe);
    if (!short)
        return 0;
    const numeric = Number(short[1].replace(/[,，]/g, ''));
    if (!Number.isFinite(numeric))
        return 0;
    const unit = short[2].toLowerCase();
    const multiplier = unit === 'w' || unit === '万' ? 10000 : 1000;
    return Math.round(numeric * multiplier);
}

xiaohongshu.summarizeCreatorNote:
export function summarizeCreatorNote(note, rows, rank) {
    const topSource = findTopBySectionPrefix(rows, '观看来源', '');
    const topInterest = findTopBySectionPrefix(rows, '观众画像', '兴趣/');
    return {
        rank,
        id: note.id,
        title: note.title,
        published_at: findDetailValue(rows, 'published_at') || note.date,
        views: findDetailValue(rows, '观看数') || String(note.views),
        likes: findDetailValue(rows, '点赞数') || String(note.likes),
        collects: findDetailValue(rows, '收藏数') || String(note.collects),
        comments: findDetailValue(rows, '评论数') || String(note.comments),
        shares: findDetailValue(rows, '分享数'),
        avg_view_time: findDetailValue(rows, '平均观看时长'),
        rise_fans: findDetailValue(rows, '涨粉数'),
        top_source: topSource.label,
        top_source_pct: topSource.value,
        top_interest: topInterest.label,
        top_interest_pct: topInterest.value,
        url: note.url,
    };
}

xiaohongshu.mapAnalyzeItems:
function mapAnalyzeItems(items) {
    return (items ?? []).map((item) => ({
        id: item.id ?? '',
        title: item.title ?? '',
        date: formatPostTime(item.post_time),
        views: item.read_count ?? 0,
        likes: item.like_count ?? 0,
        collects: item.fav_count ?? 0,
        comments: item.comment_count ?? 0,
        url: buildNoteDetailUrl(item.id),
    }));
}

twitter_device_follow:
function shapeRow({ tweetId, tweet, user }) {
    const screenName = user.screen_name;
    return {
        id: tweetId,
        author: screenName,
        text: tweet?.full_text || tweet?.text || '',
        likes: tweet?.favorite_count ?? 0,
        retweets: tweet?.retweet_count ?? 0,
        replies: tweet?.reply_count ?? 0,
        // The legacy v1.1 endpoint does not return view counts even with
        // include_ext_views=true; surface null rather than a 0 sentinel
        // that would lie about real engagement (typed-errors §3).
        views: null,
        created_at: tweet?.created_at || '',
        url: `https://x.com/${screenName}/status/${tweetId}`,
    };
}

twitter_quoted:
export function extractQuotedTweet(tweet) {
    const legacy = tweet?.legacy;
    if (!legacy?.is_quote_status) return null;
    const q = tweet?.quoted_status_result?.result
        ?? tweet?.legacy?.quoted_status_result?.result;
    // `result` can be a tombstone (`__typename: 'TweetTombstone'`) or
    // `'TweetUnavailable'` when the quoted tweet was deleted / privacy-restricted —
    // it has no `legacy`, so the downstream null-check covers both cases.
    if (!q) return null;
    // Nested `tweet` wrapper appears on TweetWithVisibilityResults — same
    // shim that callers already do at the top level (`tw.tweet || tw`).
    const qTw = q.tweet || q;
    if (!qTw || typeof qTw !== 'object') return null;
    const qLegacy = qTw.legacy && typeof qTw.legacy === 'object' ? qTw.legacy : {};
    // `rest_id` is required — tombstoned / unavailable wrappers have neither
    // rest_id nor legacy. Don't fall back to outer `legacy.quoted_status_id_str`:
    // the id alone can't substitute for missing content (author/text/media all
    // empty), so emitting a stub object would mislead downstream renderers into
    // drawing an empty "quoted tweet" preview.
    if (typeof qTw.rest_id !== 'string' || !qTw.rest_id.trim()) return null;
    const qUser = qTw.core?.user_results?.result;
    const qLegacyScreenName = qUser?.legacy?.screen_name;
    const qCoreScreenName = qUser?.core?.screen_name;
    const qScreenName = typeof qLegacyScreenName === 'string' && qLegacyScreenName.trim()
        ? qLegacyScreenName.trim()
        : (typeof qCoreScreenName === 'string' && qCoreScreenName.trim() ? qCoreScreenName.trim() : '');
    if (!SCREEN_NAME_PATTERN.test(qScreenName)) return null;
    const qLegacyDisplayName = qUser?.legacy?.name;
    const qCoreDisplayName = qUser?.core?.name;
    const qDisplayName = typeof qLegacyDisplayName === 'string'
        ? qLegacyDisplayName
        : (typeof qCoreDisplayName === 'string' ? qCoreDisplayName : '');
    const qNoteText = qTw.note_tweet?.note_tweet_results?.result?.text;
    const qText = (typeof qNoteText === 'string' && qNoteText.length > 0)
        ? qNoteText
        : (typeof qLegacy.full_text === 'string' ? qLegacy.full_text : '');
    const qMedia = extractMedia(qLegacy);
    const qCard = extractCard(qTw);
    if (!qText && !qMedia.has_media && !qCard) return null;
    const out = {
        id: qTw.rest_id,
        author: qScreenName,
        name: qDisplayName,
        text: qText,
        created_at: typeof qLegacy.created_at === 'string' ? qLegacy.created_at : '',
        url: `https://x.com/${qScreenName}/status/${qTw.rest_id}`,
        has_media: qMedia.has_media,
        media_urls: qMedia.media_urls,
        media_posters: qMedia.media_posters,
        media_durations: qMedia.media_durations,
    };
    if (qCard) out.card = qCard;
    return out;
}
